def to_csv(rows, cols):
    def cell(v):
        s = "" if v is None else str(v)
        if any(c in s for c in ',"\n'):
            return '"' + s.replace('"', '""') + '"'
        return s
    lines = [",".join(cell(c) for c in cols)]
    for r in rows:
        lines.append(",".join(cell(r.get(c)) for c in cols))
    return "\n".join(lines)

