from urllib.parse import unquote_plus
def parse_query(qs):
    out = {}
    for part in (qs or "").split("&"):
        if not part:
            continue
        k, _, v = part.partition("=")
        out[unquote_plus(k)] = unquote_plus(v)
    return out

